import{_ as i,l as n,o as e,c as s,v as o,p as l,x as t,d,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"新闻冲击与信心","description":"","frontmatter":{"title":"新闻冲击与信心","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/news-shocks.md","filePath":"econ/news-shocks.md","lastUpdated":1789023840000}'),p={name:"econ/news-shocks.md"};function m(h,a,B,A,_,u){const r=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="新闻冲击与信心" tabindex="-1">新闻冲击与信心 <a class="header-anchor" href="#新闻冲击与信心" aria-label="Permalink to &quot;新闻冲击与信心&quot;">​</a></h1><div class="epigraph"><p>关于未来技术或政策的消息今天就进欧拉与 $q$，繁荣可以发生在果实落地之前；若消息是噪声，繁荣会退潮。</p><footer>—— Beaudry and Portier, Stock Prices, News, and Economic Fluctuations, AER 2006；Jaimovich and Rebelo；Barsky and Sims</footer></div><p><a href="/econ/diagnostic-expectations">上一课</a>把过冲写成偏差。本课缺口是 <strong>RE 下的新闻</strong>：信息集提前，不必扭曲概率。不重写代表性启发，不把「动物精神」当残差标签用完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准 RBC：TFP 今天升，今天产出升。Beaudry–Portier：股市与 TFP 的识别显示，许多宏观波动像是对未来 TFP 的提前消息。新闻冲击下，消费想升、劳动想降（财富效应），需要补偏好、投资调整或互补才能让繁荣有就业——Jaimovich–Rebelo。缺口是：识别课的「冲击」可以是信息到达，而不是当前资源。信心：若消息不准，实现打脸，IRF 在中期反转。</p><p><span class="marginnote">Beaudry and Portier, <em>AER</em> 96(4), 2006。Barsky and Sims, <em>JME</em> 2011。Schmitt-Grohé and Uribe 把新闻写进估计 DSGE。Lorenzoni 的噪声需求冲击。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态含「已宣布未实现」的未来 \\(z\\)。欧拉与 \\(q\\) 立即跳。SVAR：用长期 TFP 与当期宏观的零限制，或用股市当新闻的前向变量——识别脆弱，正是叙事/高频课警告过的。DSGE：给技术过程加 MA 或提前信号，贝叶斯估新闻份额。与诊断性对照：RE 新闻的反转来自噪声实现，不是系统性过加权。</p>',8)),(e(),l(c,null,{default:t(()=>[E(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E5%85%B3%E4%BA%8E%E6%9C%AA%E6%9D%A5%E7%9A%84%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20EQ%5B%22%E4%BB%8A%E5%A4%A9%E7%9A%84%E6%AC%A7%E6%8B%89%E4%B8%8E%20q%22%5D%0A%20%20EQ%20--%3E%20BOOM%5B%22%E6%8F%90%E5%89%8D%E7%B9%81%E8%8D%A3%22%5D%0A%20%20REAL%5B%22%E5%AE%9E%E7%8E%B0%20%2F%20%E6%89%93%E8%84%B8%22%5D%20--%3E%20REV%5B%22%E6%88%96%E7%BB%A7%E7%BB%AD%E6%88%96%E9%80%80%E6%BD%AE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>财政与货币也可以有新闻（Ramey 军费公告）。本课装置通用，例子以技术新闻为钉子。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是前瞻。完全信息 RE 下，可预测的未来已经进价格；「新闻」指相对昨天的信息集扩大。粘性信息下，新闻只进入更新者。HANK 下，新闻若先抬资产价格，债权人与房主的财富效应与约束家庭的工资预期分道。信心调查是后课数据，本课先给结构对象：信号精度。</p><p>与不确定性（下一课）：新闻改变条件均值；不确定性改变条件方差。可同时到达（Bloom 的坏消息常伴高波动）。</p><p><span class="marginnote">Pigou 周期是思想前身。本课用现代识别与 DSGE 新闻过程，不写思想史全文。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每一轮牛市当成 TFP 新闻。不估计因子风险溢价。太阳黑子是没有关于基本面的新闻的信念波动，BK 不定时才进；本课默认有信号。沟通课会把政策新闻从技术新闻里拆出。</p><p>后课默认：冲击可以是信息到达；就业对新闻的符号依赖互补与偏好。下一课：方差冲击。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>新闻冲击：未来基本面的信号先动今天的量价。</li><li>RE 下也可有反转，若信号有噪。</li><li>与诊断性过冲、与纯太阳黑子分列。</li><li>出处：Beaudry and Portier, <em>AER</em> 2006；Barsky and Sims, <em>JME</em> 2011。</li></ul>',10))])}const f=i(p,[["render",m]]);export{S as __pageData,f as default};
